mapper.select:
SELECT
    (SELECT COUNT(*)
     FROM major m
     WHERE m.deleted = 0

         AND m.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS major_count,
    (SELECT COUNT(*)
     FROM student s
     JOIN major m ON s.major_id = m.major_id AND m.deleted = 0
     WHERE s.deleted = 0

         AND s.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS student_count,
    (SELECT COUNT(*)
     FROM teacher t
     WHERE t.deleted = 0

         AND t.dept_id = (SELECT dept_id FROM major WHERE major_id = #{majorId} AND deleted = 0)


         AND t.dept_id = #{deptId}
     ) AS teacher_count,
    (SELECT COUNT(*)
     FROM course c
     JOIN major m ON c.major_id = m.major_id AND m.deleted = 0
     WHERE c.deleted = 0

         AND c.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS course_count,
    (SELECT COUNT(*)
     FROM achievement a
     JOIN teacher t ON a.teacher_id = t.teacher_id AND t.deleted = 0
     WHERE a.deleted = 0

         AND a.stat_year = #{year}


         AND t.dept_id = (SELECT dept_id FROM major WHERE major_id = #{majorId} AND deleted = 0)


         AND t.dept_id = #{deptId}
     ) AS achievement_count,
    (SELECT IFNULL(ROUND((SUM(CASE WHEN t.phd_flag = 1 THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0)) * 100, 2), 0)
     FROM teacher t
     WHERE t.deleted = 0

         AND t.dept_id = (SELECT dept_id FROM major WHERE major_id = #{majorId} AND deleted = 0)


         AND t.dept_id = #{deptId}
     ) AS phd_rate,
    (SELECT IFNULL(ROUND(SUM(a.actual_count) / NULLIF(SUM(a.plan_count), 0) * 100, 2), 0)
     FROM admission a
     JOIN major m ON a.major_id = m.major_id AND m.deleted = 0
     WHERE a.deleted = 0

         AND a.stat_year = #{year}


         AND a.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS admission_completion_rate,
    (SELECT IFNULL(SUM(a.plan_count), 0)
     FROM admission a
     JOIN major m ON a.major_id = m.major_id AND m.deleted = 0
     WHERE a.deleted = 0

         AND a.stat_year = #{year}


         AND a.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS admission_plan_total,
    (SELECT IFNULL(SUM(a.actual_count), 0)
     FROM admission a
     JOIN major m ON a.major_id = m.major_id AND m.deleted = 0
     WHERE a.deleted = 0

         AND a.stat_year = #{year}


         AND a.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS admission_actual_total,
    (SELECT IFNULL(ROUND(SUM(IFNULL(f.spent, 0)) / NULLIF(SUM(IFNULL(f.allocated, 0)), 0) * 100, 2), 0)
     FROM funding f
     JOIN major m ON f.major_id = m.major_id AND m.deleted = 0
     WHERE f.deleted = 0

         AND f.stat_year = #{year}


         AND f.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS funding_utilization_rate,
    (SELECT IFNULL(SUM(IFNULL(f.allocated, 0)), 0)
     FROM funding f
     JOIN major m ON f.major_id = m.major_id AND m.deleted = 0
     WHERE f.deleted = 0

         AND f.stat_year = #{year}


         AND f.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS funding_allocated_total,
    (SELECT IFNULL(SUM(IFNULL(f.spent, 0)), 0)
     FROM funding f
     JOIN major m ON f.major_id = m.major_id AND m.deleted = 0
     WHERE f.deleted = 0

         AND f.stat_year = #{year}


         AND f.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS funding_spent_total,
    (SELECT COUNT(*)
     FROM competition c
     JOIN student s ON c.student_id = s.student_id AND s.deleted = 0
     JOIN major m ON s.major_id = m.major_id AND m.deleted = 0
     WHERE c.deleted = 0

         AND c.stat_year = #{year}


         AND s.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS competition_award_count,
    (SELECT IFNULL(ROUND(SUM(go.employment_rate * go.graduate_count) / NULLIF(SUM(go.graduate_count), 0), 2), 0)
     FROM graduate_outcome go
     JOIN major m ON go.major_id = m.major_id AND m.deleted = 0
     WHERE go.deleted = 0

         AND go.stat_year = #{year}


         AND go.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS employment_rate,
    (SELECT IFNULL(ROUND(SUM(go.postgraduate_rate * go.graduate_count) / NULLIF(SUM(go.graduate_count), 0), 2), 0)
     FROM graduate_outcome go
     JOIN major m ON go.major_id = m.major_id AND m.deleted = 0
     WHERE go.deleted = 0

         AND go.stat_year = #{year}


         AND go.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS postgraduate_rate,
    (SELECT IFNULL(ROUND(SUM(go.average_salary * go.graduate_count) / NULLIF(SUM(go.graduate_count), 0), 2), 0)
     FROM graduate_outcome go
     JOIN major m ON go.major_id = m.major_id AND m.deleted = 0
     WHERE go.deleted = 0

         AND go.stat_year = #{year}


         AND go.major_id = #{majorId}


         AND m.dept_id = #{deptId}
     ) AS average_salary

choose.when:
SELECT a.stat_year, COUNT(*) AS metric_value FROM achievement a JOIN teacher t ON a.teacher_id = t.teacher_id AND t.deleted = 0 WHERE a.deleted = 0 AND a.stat_year BETWEEN #{startYear} AND #{endYear}
AND t.dept_id = (SELECT dept_id FROM major WHERE major_id = #{majorId} AND deleted = 0)
AND t.dept_id = #{deptId}
GROUP BY a.stat_year ORDER BY a.stat_year

SELECT c.stat_year, COUNT(*) AS metric_value
FROM competition c
JOIN student s ON c.student_id = s.student_id AND s.deleted = 0
JOIN major m ON s.major_id = m.major_id AND m.deleted = 0
WHERE c.deleted = 0
  AND c.stat_year BETWEEN #{startYear} AND #{endYear}

    AND s.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY c.stat_year
ORDER BY c.stat_year

SELECT go.stat_year, IFNULL(ROUND(SUM(go.average_salary * go.graduate_count) / NULLIF(SUM(go.graduate_count), 0), 2), 0) AS metric_value
FROM graduate_outcome go
JOIN major m ON go.major_id = m.major_id AND m.deleted = 0
WHERE go.deleted = 0
  AND go.stat_year BETWEEN #{startYear} AND #{endYear}

    AND go.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY go.stat_year
ORDER BY go.stat_year

SELECT a.stat_year, IFNULL(SUM(a.plan_count), 0) AS metric_value
FROM admission a
JOIN major m ON a.major_id = m.major_id AND m.deleted = 0
WHERE a.deleted = 0
  AND a.stat_year BETWEEN #{startYear} AND #{endYear}

    AND a.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY a.stat_year
ORDER BY a.stat_year

SELECT a.stat_year, IFNULL(SUM(a.actual_count), 0) AS metric_value
FROM admission a
JOIN major m ON a.major_id = m.major_id AND m.deleted = 0
WHERE a.deleted = 0
  AND a.stat_year BETWEEN #{startYear} AND #{endYear}

    AND a.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY a.stat_year
ORDER BY a.stat_year

SELECT f.stat_year, IFNULL(SUM(IFNULL(f.allocated, 0)), 0) AS metric_value
FROM funding f
JOIN major m ON f.major_id = m.major_id AND m.deleted = 0
WHERE f.deleted = 0
  AND f.stat_year BETWEEN #{startYear} AND #{endYear}

    AND f.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY f.stat_year
ORDER BY f.stat_year

SELECT f.stat_year, IFNULL(SUM(IFNULL(f.spent, 0)), 0) AS metric_value
FROM funding f
JOIN major m ON f.major_id = m.major_id AND m.deleted = 0
WHERE f.deleted = 0
  AND f.stat_year BETWEEN #{startYear} AND #{endYear}

    AND f.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY f.stat_year
ORDER BY f.stat_year

SELECT a.stat_year, IFNULL(ROUND(SUM(a.actual_count) / NULLIF(SUM(a.plan_count), 0) * 100, 2), 0) AS metric_value
FROM admission a
JOIN major m ON a.major_id = m.major_id AND m.deleted = 0
WHERE a.deleted = 0
  AND a.stat_year BETWEEN #{startYear} AND #{endYear}

    AND a.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY a.stat_year
ORDER BY a.stat_year

SELECT f.stat_year, IFNULL(ROUND(SUM(IFNULL(f.spent, 0)) / NULLIF(SUM(IFNULL(f.allocated, 0)), 0) * 100, 2), 0) AS metric_value
FROM funding f
JOIN major m ON f.major_id = m.major_id AND m.deleted = 0
WHERE f.deleted = 0
  AND f.stat_year BETWEEN #{startYear} AND #{endYear}

    AND f.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY f.stat_year
ORDER BY f.stat_year

SELECT go.stat_year, IFNULL(ROUND(SUM(go.employment_rate * go.graduate_count) / NULLIF(SUM(go.graduate_count), 0), 2), 0) AS metric_value
FROM graduate_outcome go
JOIN major m ON go.major_id = m.major_id AND m.deleted = 0
WHERE go.deleted = 0
  AND go.stat_year BETWEEN #{startYear} AND #{endYear}

    AND go.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY go.stat_year
ORDER BY go.stat_year

SELECT go.stat_year, IFNULL(ROUND(SUM(go.postgraduate_rate * go.graduate_count) / NULLIF(SUM(go.graduate_count), 0), 2), 0) AS metric_value
FROM graduate_outcome go
JOIN major m ON go.major_id = m.major_id AND m.deleted = 0
WHERE go.deleted = 0
  AND go.stat_year BETWEEN #{startYear} AND #{endYear}

    AND go.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY go.stat_year
ORDER BY go.stat_year

choose.otherwise:
SELECT c.stat_year, COUNT(*) AS metric_value
FROM competition c
JOIN student s ON c.student_id = s.student_id AND s.deleted = 0
JOIN major m ON s.major_id = m.major_id AND m.deleted = 0
WHERE c.deleted = 0
  AND c.stat_year BETWEEN #{startYear} AND #{endYear}

    AND s.major_id = #{majorId}


    AND m.dept_id = #{deptId}

GROUP BY c.stat_year
ORDER BY c.stat_year

choose.when:
SELECT m.major_id, m.name AS major_name, IFNULL(COUNT(s.student_id), 0) AS metric_value FROM major m LEFT JOIN student s ON m.major_id = s.major_id AND s.deleted = 0 WHERE m.deleted = 0
AND m.dept_id = #{deptId}
GROUP BY m.major_id, m.name ORDER BY metric_value DESC LIMIT #{limit}

SELECT m.major_id, m.name AS major_name, IFNULL((SELECT COUNT(*) FROM teacher t WHERE t.deleted = 0 AND t.dept_id = m.dept_id), 0) AS metric_value FROM major m WHERE m.deleted = 0
AND m.dept_id = #{deptId}
ORDER BY metric_value DESC LIMIT #{limit}

SELECT m.major_id, m.name AS major_name, IFNULL(a.actual_count, 0) AS metric_value
FROM major m
LEFT JOIN admission a ON m.major_id = a.major_id AND a.deleted = 0 AND a.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

ORDER BY metric_value DESC
LIMIT #{limit}

SELECT m.major_id, m.name AS major_name, IFNULL(f.spent, 0) AS metric_value
FROM major m
LEFT JOIN funding f ON m.major_id = f.major_id AND f.deleted = 0 AND f.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

ORDER BY metric_value DESC
LIMIT #{limit}

SELECT m.major_id, m.name AS major_name, IFNULL(f.allocated, 0) AS metric_value
FROM major m
LEFT JOIN funding f ON m.major_id = f.major_id AND f.deleted = 0 AND f.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

ORDER BY metric_value DESC
LIMIT #{limit}

SELECT m.major_id, m.name AS major_name, IFNULL(COUNT(c.course_id), 0) AS metric_value FROM major m LEFT JOIN course c ON m.major_id = c.major_id AND c.deleted = 0 WHERE m.deleted = 0
AND m.dept_id = #{deptId}
GROUP BY m.major_id, m.name ORDER BY metric_value DESC LIMIT #{limit}

SELECT m.major_id, m.name AS major_name, IFNULL(COUNT(a.achievement_id), 0) AS metric_value
FROM major m
LEFT JOIN teacher t ON m.dept_id = t.dept_id AND t.deleted = 0
LEFT JOIN achievement a ON t.teacher_id = a.teacher_id AND a.deleted = 0 AND a.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

GROUP BY m.major_id, m.name
ORDER BY metric_value DESC
LIMIT #{limit}

SELECT m.major_id, m.name AS major_name, IFNULL(COUNT(c.competition_id), 0) AS metric_value
FROM major m
LEFT JOIN student s ON m.major_id = s.major_id AND s.deleted = 0
LEFT JOIN competition c ON s.student_id = c.student_id AND c.deleted = 0 AND c.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

GROUP BY m.major_id, m.name
ORDER BY metric_value DESC
LIMIT #{limit}

SELECT m.major_id, m.name AS major_name, IFNULL(go.average_salary, 0) AS metric_value
FROM major m
LEFT JOIN graduate_outcome go ON m.major_id = go.major_id AND go.deleted = 0 AND go.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

ORDER BY metric_value DESC
LIMIT #{limit}

SELECT m.major_id, m.name AS major_name, IFNULL(ROUND((SELECT SUM(CASE WHEN t.phd_flag = 1 THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) * 100 FROM teacher t WHERE t.deleted = 0 AND t.dept_id = m.dept_id), 2), 0) AS metric_value FROM major m WHERE m.deleted = 0
AND m.dept_id = #{deptId}
ORDER BY metric_value DESC LIMIT #{limit}

SELECT m.major_id, m.name AS major_name,
       IFNULL(ROUND(a.actual_count / NULLIF(a.plan_count, 0) * 100, 2), 0) AS metric_value
FROM major m
LEFT JOIN admission a ON m.major_id = a.major_id AND a.deleted = 0 AND a.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

ORDER BY metric_value DESC
LIMIT #{limit}

SELECT m.major_id, m.name AS major_name,
       IFNULL(f.utilization_rate, IFNULL(ROUND(f.spent / NULLIF(f.allocated, 0) * 100, 2), 0)) AS metric_value
FROM major m
LEFT JOIN funding f ON m.major_id = f.major_id AND f.deleted = 0 AND f.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

ORDER BY metric_value DESC
LIMIT #{limit}

SELECT m.major_id, m.name AS major_name,
       IFNULL(go.employment_rate, 0) AS metric_value
FROM major m
LEFT JOIN graduate_outcome go ON m.major_id = go.major_id AND go.deleted = 0 AND go.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

ORDER BY metric_value DESC
LIMIT #{limit}

SELECT m.major_id, m.name AS major_name,
       IFNULL(go.postgraduate_rate, 0) AS metric_value
FROM major m
LEFT JOIN graduate_outcome go ON m.major_id = go.major_id AND go.deleted = 0 AND go.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

ORDER BY metric_value DESC
LIMIT #{limit}

choose.otherwise:
SELECT m.major_id, m.name AS major_name, COUNT(c.competition_id) AS metric_value
FROM major m
LEFT JOIN student s ON m.major_id = s.major_id AND s.deleted = 0
LEFT JOIN competition c ON s.student_id = c.student_id AND c.deleted = 0 AND c.stat_year = #{year}
WHERE m.deleted = 0

    AND m.dept_id = #{deptId}

GROUP BY m.major_id, m.name
ORDER BY metric_value DESC
LIMIT #{limit}

mapper.select:
SELECT m.major_id, m.name AS major_name, IFNULL(ROUND((SELECT SUM(CASE WHEN t.phd_flag = 1 THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0) * 100 FROM teacher t WHERE t.deleted = 0 AND t.dept_id = m.dept_id), 2), 0) AS phd_rate, IFNULL((SELECT ROUND(a.actual_count / NULLIF(a.plan_count, 0) * 100, 2) FROM admission a WHERE a.deleted = 0 AND a.major_id = m.major_id AND a.stat_year = #{year} ORDER BY a.stat_year DESC LIMIT 1), 0) AS admission_completion_rate, IFNULL((SELECT IFNULL(f.utilization_rate, ROUND(f.spent / NULLIF(f.allocated, 0) * 100, 2)) FROM funding f WHERE f.deleted = 0 AND f.major_id = m.major_id AND f.stat_year = #{year} ORDER BY f.stat_year DESC LIMIT 1), 0) AS funding_utilization_rate, IFNULL((SELECT go.employment_rate FROM graduate_outcome go WHERE go.deleted = 0 AND go.major_id = m.major_id AND go.stat_year = #{year} ORDER BY go.stat_year DESC LIMIT 1), 0) AS employment_rate, IFNULL((SELECT go.postgraduate_rate FROM graduate_outcome go WHERE go.deleted = 0 AND go.major_id = m.major_id AND go.stat_year = #{year} ORDER BY go.stat_year DESC LIMIT 1), 0) AS postgraduate_rate, 0 AS total_score FROM major m WHERE m.deleted = 0
AND m.major_id = #{majorId}
AND m.dept_id = #{deptId}
ORDER BY m.major_id

SELECT w.warning_id, w.major_id, m.name AS major_name, w.indicator_code, w.indicator_name, w.stat_year,
       w.threshold_value, w.actual_value, w.status, w.message, w.triggered_at
FROM warning_record w
JOIN major m ON w.major_id = m.major_id AND m.deleted = 0
WHERE w.deleted = 0
  AND w.status = 'ACTIVE'

    AND w.stat_year = #{year}


    AND w.major_id = #{majorId}


    AND m.dept_id = #{deptId}

ORDER BY w.triggered_at DESC
